CREATE TABLE IF NOT EXISTS gis_spatial_identity_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, source_feature_id TEXT NOT NULL, target_feature_id TEXT NOT NULL, source_provider TEXT NOT NULL, target_provider TEXT NOT NULL, source_geometry_valid BOOLEAN, target_geometry_valid BOOLEAN, source_area DOUBLE PRECISION, target_area DOUBLE PRECISION, intersection_area DOUBLE PRECISION, source_overlap_ratio DOUBLE PRECISION, target_overlap_ratio DOUBLE PRECISION, iou DOUBLE PRECISION, name_similarity DOUBLE PRECISION, state_match BOOLEAN, spatial_score DOUBLE PRECISION, identity_score DOUBLE PRECISION, combined_score DOUBLE PRECISION, confidence TEXT, decision TEXT, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id,target_feature_id));